M.Aggregation.callTemplate:
agg_fn <- switch("<agg_func>",
  sum = function(x) sum(x, na.rm = TRUE),
  count = function(x) sum(!is.na(x)),
  mean = function(x) mean(x, na.rm = TRUE),
  max = function(x) max(x, na.rm = TRUE),
  min = function(x) min(x, na.rm = TRUE),
  first = function(x) x[1],
  last = function(x) x[length(x)],
  function(x) sum(x, na.rm = TRUE)
)
value_cols <- strsplit("<value>", " \\+ ")[[1]]
result_col <- "<result>"
agg_axis <- "<axis>"
# Transformations authored before the axis config exists leave the placeholder
# unsubstituted; anything that isn't a known axis falls back to the old behaviour.
if (!(agg_axis %in% c("rows", "roles"))) agg_axis <- "rows"

if (agg_axis == "roles") {
  # Aggregate ACROSS the values bound to the value role on each record. Record
  # count is unchanged and partition is ignored -- this is the elementwise
  # "earliest of these dates" operation, not a rollup.
  present <- value_cols[value_cols %in% colnames(concept_data)]
  if (length(present) == 0) {
    stop(sprintf("M.Aggregation(axis=roles): none of the value columns '%s' are present. concept_data: %s",
                 paste(value_cols, collapse = ", "), paste(colnames(concept_data), collapse = ", ")))
  }
  all_numeric <- all(vapply(present, function(cc) is.numeric(concept_data[[cc]]), logical(1)))
  block <- concept_data[, present, drop = FALSE]
  if (all_numeric) {
    concept_data[[result_col]] <- apply(as.matrix(block), 1, function(row) {
      row <- row[!is.na(row)]
      if (length(row) == 0) NA_real_ else agg_fn(row)
    })
  } else {
    # ISO-8601 dates order lexically, so min/max are chronological on character.
    concept_data[[result_col]] <- apply(block, 1, function(row) {
      row <- as.character(row)
      row <- row[!is.na(row) & trimws(row) != ""]
      if (length(row) == 0) NA_character_ else as.character(agg_fn(row))
    })
  }
} else {
  partition_cols <- strsplit("<partition>", " \\+ ")[[1]]
  partition_cols <- partition_cols[partition_cols %in% colnames(concept_data)]
  val_col <- value_cols[1]
  # Source for aggregation: prefer the leaf snapshot if it has the value column
  # (sibling aggregations after upstream rollups would otherwise have nothing
  # to aggregate), else fall back to the running cube (for aggregations over
  # upstream-derived columns whose leaf form doesn't exist).
  src <- if (!is.null(concept_data_leaf) && val_col %in% colnames(concept_data_leaf)) concept_data_leaf else concept_data
  if (!(val_col %in% colnames(src))) {
    stop(sprintf("M.Aggregation: value column '%s' not found. concept_data: %s. concept_data_leaf: %s", val_col, paste(colnames(concept_data), collapse=", "), if (is.null(concept_data_leaf)) "<null>" else paste(colnames(concept_data_leaf), collapse=", ")))
  }
  if (length(partition_cols) > 0) {
    agg_result <- aggregate(
      stats::as.formula(paste0("`", val_col, "` ~ ", paste0("`", partition_cols, "`", collapse = " + "))),
      data = src, FUN = agg_fn
    )
    colnames(agg_result)[colnames(agg_result) == val_col] <- result_col
    # Broadcast the per-group aggregate back onto the running cube. Cube
    # collapse + slice projection happen ONCE at chain end (in the engine
    # post-processing), not here -- different aggregations in a chain may
    # partition on different dimensions (e.g. per-Parameter max, per-Subject
    # sum), so collapsing at each step would destroy lookups for siblings.
    if (result_col %in% colnames(concept_data)) concept_data[[result_col]] <- NULL
    concept_data <- merge(concept_data, agg_result, by = partition_cols, all.x = TRUE)
  } else {
    concept_data[[result_col]] <- agg_fn(src[[val_col]])
  }
}

M.ConditionalValue.callTemplate:
val <- concept_data[["<value>"]]
alt <- concept_data[["<alternate>"]]
base_cfg <- "<base>"
missing <- is.na(val) | trimws(as.character(val)) == ""
missing[is.na(missing)] <- TRUE
if (base_cfg == "value") {
  # Coalesce: keep <value>, fall back to <alternate>. Type is preserved so the
  # same method works on dates as on numbers.
  if (is.numeric(val) && is.numeric(alt)) {
    res <- ifelse(missing, alt, val)
  } else {
    res <- ifelse(missing, as.character(alt), as.character(val))
    res[!is.na(res) & trimws(res) == ""] <- NA
  }
} else {
  res <- ifelse(missing, as.numeric(alt), as.numeric(base_cfg))
}
concept_data[["<result>"]] <- res
